import asyncio
import uuid

from alembic import command
from alembic.config import Config
from sqlalchemy import make_url
from sqlalchemy.ext.asyncio import create_async_engine


def alembic_config(url: str) -> Config:
    config = Config("alembic.ini")
    config.set_main_option("sqlalchemy.url", url)
    return config


def test_models_match_migrations(database_url: str) -> None:
    # fails with AutoGenerateDiffsDetected if a model change has no migration
    command.check(alembic_config(database_url))


def test_downgrade_and_upgrade_again(database_url: str) -> None:
    name = f"migrations_{uuid.uuid4().hex[:8]}"
    asyncio.run(_execute(database_url, f'CREATE DATABASE "{name}"'))
    try:
        config = alembic_config(make_url(database_url).set(database=name).render_as_string(False))
        command.upgrade(config, "head")
        command.downgrade(config, "base")
        command.upgrade(config, "head")
    finally:
        asyncio.run(_execute(database_url, f'DROP DATABASE "{name}"'))


async def _execute(url: str, statement: str) -> None:
    engine = create_async_engine(url, isolation_level="AUTOCOMMIT")
    try:
        async with engine.connect() as connection:
            await connection.exec_driver_sql(statement)
    finally:
        await engine.dispose()
